static inline const CD_PROJECTILE_AREA *CopydogProjectileArea(int id)
{
    size_t lo=0, hi=sizeof CopydogProjectileAreaRows/sizeof CopydogProjectileAreaRows[0];
    while(lo<hi){
        size_t mid=lo+(hi-lo)/2;
        const CD_PROJECTILE_AREA *row=&CopydogProjectileAreaRows[mid];
        if(id<row->id)hi=mid;
        else if(id>row->id)lo=mid+1;
        else return row;
    }
    return NULL;
}
